# kaniko-docker-config-secret.yaml
apiVersion: v1
kind: Secret
metadata:
  name: kaniko-docker-config
  namespace: ci-builds
type: kubernetes.io/dockerconfigjson
stringData:
  .dockerconfigjson: |
    {
      "auths": {
        "registry.cn-hangzhou.aliyuncs.com": {
          "auth": "${BASE64_ENCODED_AUTH}"
        },
        "ghcr.io": {
          "auth": "${GITHUB_TOKEN_BASE64}"
        }
      },
      "credHelpers": {
        "gcr.io": "gcr",
        "us.gcr.io": "gcr",
        "eu.gcr.io": "gcr",
        "asia.gcr.io": "gcr"
      }
    }

// Jenkinsfile - Jenkins Pipeline 集成
pipeline {
    agent {
        kubernetes {
            yaml '''
apiVersion: v1
kind: Pod
spec:
  containers:
  - name: kaniko
    image: gcr.io/kaniko-project/executor:debug
    command:
    - sleep
    args:
    - infinity
    volumeMounts:
    - name: docker-config
      mountPath: /kaniko/.docker/
  - name: trivy
    image: aquasec/trivy:latest
    command:
    - sleep
    args:
    - infinity
  volumes:
  - name: docker-config
    secret:
      secretName: kaniko-docker-config
'''
        }
    }

    environment {
        REGISTRY = 'registry.cn-hangzhou.aliyuncs.com/myns'
        IMAGE_NAME = 'myapp'
    }

    stages {
        stage('Build') {
            steps {
                container('kaniko') {
                    sh '''
                        /kaniko/executor \
                            --context ${WORKSPACE} \
                            --dockerfile ${WORKSPACE}/Dockerfile \
                            --destination ${REGISTRY}/${IMAGE_NAME}:${BUILD_NUMBER} \
                            --destination ${REGISTRY}/${IMAGE_NAME}:${GIT_COMMIT} \
                            --cache=true \
                            --cache-repo=${REGISTRY}/${IMAGE_NAME}/cache \
                            --digest-file /tmp/image-digest
                    '''
                    script {
                        env.IMAGE_DIGEST = sh(script: 'cat /tmp/image-digest', returnStdout: true).trim()
                    }
                }
            }
        }

        stage('Scan') {
            steps {
                container('trivy') {
                    sh """
                        trivy image \
                            --exit-code 1 \
                            --severity HIGH,CRITICAL \
                            --format table \
                            ${REGISTRY}/${IMAGE_NAME}@${IMAGE_DIGEST}
                    """
                }
            }
        }
    }
}

// build.gradle.kts
plugins {
    id("java")
    id("org.springframework.boot") version "3.2.0"
    id("com.google.cloud.tools.jib") version "3.4.0"
}

jib {
    from {
        image = "eclipse-temurin:21-jre-alpine"
        platforms {
            platform {
                architecture = "amd64"
                os = "linux"
            }
            platform {
                architecture = "arm64"
                os = "linux"
            }
        }
    }

    to {
        image = "registry.cn-hangzhou.aliyuncs.com/myns/${project.name}"
        tags = setOf(project.version.toString(), "latest")
        auth {
            username = System.getenv("REGISTRY_USER")
            password = System.getenv("REGISTRY_PASSWORD")
        }
    }

    container {
        jvmFlags = listOf(
            "-Xms512m",
            "-Xmx2g",
            "-XX:+UseG1GC",
            "-XX:+UseContainerSupport",
            "-XX:MaxRAMPercentage=75.0"
        )
        mainClass = "com.example.Application"
        ports = listOf("8080", "8081")
        environment = mapOf(
            "SPRING_PROFILES_ACTIVE" to "production",
            "TZ" to "Asia/Shanghai"
        )
        labels.set(mapOf(
            "org.opencontainers.image.title" to project.name,
            "org.opencontainers.image.version" to project.version.toString()
        ))
        user = "1000:1000"
        workingDirectory = "/app"
        creationTime.set("USE_CURRENT_TIMESTAMP")
    }

    extraDirectories {
        paths {
            path {
                setFrom("src/main/jib")
                into = "/app"
            }
        }
        permissions.set(mapOf(
            "/app/entrypoint.sh" to "755"
        ))
    }
}
